        resetAceitePasos: ["Aprieta deprisa el botón Start 3 veces seguidas, sin tocar el freno, hasta que el cuadro enseñe 'Diagnostic Mode Active'.", "Deja BC apretado durante unos 15-20 segundos —es el botón de la palanca de intermitentes— hasta ver el menú de servicio correspondiente.", "Pulsa BC con pulsaciones cortas para pasar por los puntos de servicio (filtro de ventilación, líquido de frenos...); cada uno indica si se puede resetear.", "En el punto deseado, mantén BC pulsado hasta que se muestre 'Reset?', suelta y vuelve a pulsarlo manteniéndolo para confirmar ('reset successful') en pantalla.", "Cuando quieras salir del modo de diagnóstico, corta el coche con el botón Start."],
        resetAceiteNota: "Ahora, en un eléctrico no hay punto de aceite que resetear: solo quedan por poner a cero los puntos CBS, es decir, el líquido de frenos, la revisión del vehículo y el filtro de ventilación.",
        intervaloMantenimiento: "CBS (Condition Based Service): no hay intervalo fijo por km; el coche avisa en función del uso (líquido de frenos cada 2 años de plazo)",
        filtroPolenUbicacion: "Detrás del compartimento del copiloto",
        filtroPolenPasos: ["Despeja la guantera y déjala vacía.", "Retira el embellecedor inferior de la guantera, que va con 2 tornillos de 10 mm, desconectando los conectores de alimentación de la luz de la guantera.", "Suelta los 2 tornillos T-15 que sujetan la tapa del alojamiento del filtro y déjala apartada.", "Saca el filtro viejo observando hacia dónde señala la flecha de flujo de aire correspondiente.", "Monta el repuesto con la flecha orientada igual que la anterior y rearma todo en orden inverso."],
        videoTutorialUrl: "https://www.youtube.com/watch?v=HNiJO8_ckiY",
        videoTutorialTitulo: "How to reset oil, and reset brake pads \"reset unsuccessful\" on BMW",
